export function getAllTools(includeV2Compat = true): MCPTool[] {
  const v3Tools = [
    ...agentTools,
    ...swarmTools,
    ...memoryTools,
    ...configTools,
    ...hooksTools,
    ...taskTools,
    ...systemTools,
    ...sessionTools,
    ...workerTools,
    ...sonaTools,
    ...federationTools,
  ];

