/**
 * Get tool by name
 *
 * Returns a specific tool by its name.
 *
 * @param name - Tool name (e.g., 'agent/spawn')
 * @returns The tool if found, undefined otherwise
 *
 * @example
 * ```typescript
 * import { getToolByName } from './mcp/tools/index.js';
