/**
 * Get tools by tag
 *
 * Returns all tools that have a specific tag.
 *
 * @param tag - Tag to filter by
 * @returns Array of tools with the specified tag
 *
 * @example
 * ```typescript
 * import { getToolsByTag } from './mcp/tools/index.js';
