    const duplicates = allTools.filter(t => t.name === tool.name);
    if (duplicates.length > 1) {
      issues.push({ tool: tool.name, issue: 'Duplicate tool name' });
    }
  });

  return {
    valid: issues.length === 0,
    issues,
  };
