        learningCycles: 0,
        totalSearchLatency: 0,
        totalCycleDuration: 0,
        lastLearningCycle: null,
    };
    constructor() {
        // Initialize default profiles
        this.initializeProfiles();
    }
    static getInstance() {
        if (!SONAState.instance) {
            SONAState.instance = new SONAState();
        }
        return SONAState.instance;
    }
    initializeProfiles() {
        const profiles = [
            {
                id: 'default',
