                },
            },
        ];
        for (const profile of profiles) {
            this.profiles.set(profile.id, profile);
        }
    }
    generateId(prefix) {
        return `${prefix}_${Date.now().toString(36)}_${Math.random().toString(36).slice(2, 8)}`;
    }
}
function getState() {
    return SONAState.getInstance();
