/**
 * Get overall system status
 */
async function handleSystemStatus(input, context) {
    const timestamp = new Date().toISOString();
    const uptime = process.uptime();
    const version = '3.0.0'; // V3 version
    const components = [];
    let overallStatus = 'healthy';
    // Check MCP server
    components.push({
        name: 'mcp-server',
        status: 'healthy',
        lastCheck: timestamp,
        message: 'MCP server is running',
    });
    // Check orchestrator if available
    if (context?.orchestrator) {
        try {
            const orchestrator = context.orchestrator;
            const status = await orchestrator.getStatus();
            components.push({
                name: 'orchestrator',
                status: status.healthy ? 'healthy' : 'degraded',
                lastCheck: timestamp,
                details: status,
            });
        }
        catch (error) {
            components.push({
                name: 'orchestrator',
                status: 'unknown',
                lastCheck: timestamp,
                message: 'Failed to get orchestrator status',
            });
        }
    }
    // Check swarm coordinator if available
    if (context?.swarmCoordinator) {
        try {
            const coordinator = context.swarmCoordinator;
            const status = await coordinator.getStatus();
            components.push({
                name: 'swarm-coordinator',
                status: status.state === 'ready' ? 'healthy' :
                    status.state === 'degraded' ? 'degraded' : 'unhealthy',
                lastCheck: timestamp,
                details: { state: status.state, agentCount: status.agents?.length },
            });
        }
        catch (error) {
            components.push({
                name: 'swarm-coordinator',
                status: 'unknown',
                lastCheck: timestamp,
                message: 'Failed to get swarm status',
            });
        }
    }
    // Check memory service if available
    const resourceManager = context?.resourceManager;
    if (resourceManager?.memoryService) {
        try {
            const memoryService = resourceManager.memoryService;
            const stats = await memoryService.getStats();
            components.push({
                name: 'memory-service',
                status: 'healthy',
                lastCheck: timestamp,
                details: { entryCount: stats.entryCount, size: stats.size },
            });
        }
        catch (error) {
            components.push({
                name: 'memory-service',
                status: 'unknown',
                lastCheck: timestamp,
                message: 'Failed to get memory service status',
            });
        }
    }
