    const hasUnhealthy = components.some(c => c.status === 'unhealthy');
    const hasDegraded = components.some(c => c.status === 'degraded');
    if (hasUnhealthy) {
        overallStatus = 'unhealthy';
    }
    else if (hasDegraded) {
        overallStatus = 'degraded';
    }
    const result = {
        status: overallStatus,
        timestamp,
        uptime,
        version,
        components,
    };
    // Include agent information
    if (input.includeAgents && context?.swarmCoordinator) {
        try {
            const coordinator = context.swarmCoordinator;
            const status = await coordinator.getStatus();
            const agents = status.agents || [];
            result.agents = {
                total: agents.length,
                active: agents.filter((a) => a.status === 'active').length,
                idle: agents.filter((a) => a.status === 'idle').length,
                terminated: agents.filter((a) => a.status === 'terminated').length,
            };
        }
        catch (error) {
            result.agents = { total: 0, active: 0, idle: 0, terminated: 0 };
        }
    }
    // Include task information
    if (input.includeTasks && context?.orchestrator) {
        try {
            const orchestrator = context.orchestrator;
            const tasks = await orchestrator.listTasks({ limit: 10000 });
            result.tasks = {
                total: tasks.total,
                pending: tasks.tasks.filter((t) => t.status === 'pending').length,
                running: tasks.tasks.filter((t) => t.status === 'running').length,
                completed: tasks.tasks.filter((t) => t.status === 'completed').length,
                failed: tasks.tasks.filter((t) => t.status === 'failed').length,
